class Node:
    def __init__(self, l, r):
        self.l = l
        self.r = r
        self.left = None
        self.right = None

    def insert(self, node):
        if node.l <= self.l and self.r <= node.r:
            return True

        if self.l > node.r or self.r < node.l:
            return False

        if node.l < self.l:
            self.left = Node(node.l, self.l))
            self.left.insert(node)

        if node.r > self.r:
            self.right = Node(self.r, node.r))
            self.right.insert(node)

        return True


